package ru.reader.rsvp;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Preview-and-consent UI for URLs. Never starts downloading before user confirmation. */
public class UrlImportActivity extends Activity {
    LinearLayout root,chapters;EditText address;TextView status,title,summary,overall;ImageView coverPreview;Button download,all,none,find;KvuheParser.Book preview;ArrayList<CheckBox> checks=new ArrayList<>();Handler handler=new Handler(Looper.getMainLooper());
    int background=0xfff3e7d5,foreground=0xff30221e;
    int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(14));return d;}
    TextView text(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(foreground);t.setPadding(dp(6),dp(7),dp(6),dp(7));return t;}
    void add(LinearLayout p,android.view.View v){p.addView(v,new LinearLayout.LayoutParams(-1,-2));}
    Button button(String t){Button b=new Button(this);b.setText(t);b.setAllCaps(false);return b;}
    @Override public void onCreate(Bundle b){super.onCreate(b);android.content.SharedPreferences p=getSharedPreferences("reader",0);background=p.getInt("bg",background);foreground=p.getInt("fg",foreground);draw();}
    void draw(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setPadding(dp(15),dp(24),dp(15),dp(18));root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background);scroll.addView(root);setContentView(scroll);
        add(root,text("←  Импорт по ссылке",23));Button queue=button("Очередь загрузок");add(root,queue);queue.setOnClickListener(v->startActivity(new Intent(this,DownloadActivity.class)));address=new EditText(this);address.setSingleLine(true);address.setHint("https://knigavuhe.org/book/...");address.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);add(root,address);String requested=getIntent().getStringExtra("source");if(requested!=null)address.setText(requested);
        LinearLayout row=new LinearLayout(this);root.addView(row);Button paste=button("Вставить");row.addView(paste,new LinearLayout.LayoutParams(0,-2,1));paste.setOnClickListener(v->{android.content.ClipboardManager clip=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(clip.hasPrimaryClip()&&clip.getPrimaryClip().getItemCount()>0)address.setText(clip.getPrimaryClip().getItemAt(0).coerceToText(this));});find=button("Найти аудиокнигу");row.addView(find,new LinearLayout.LayoutParams(0,-2,2));find.setOnClickListener(v->fetch());
        coverPreview=new ImageView(this);coverPreview.setScaleType(ImageView.ScaleType.CENTER_INSIDE);root.addView(coverPreview,new LinearLayout.LayoutParams(-1,dp(155)));coverPreview.setVisibility(View.GONE);title=text("",21);add(root,title);summary=text("",15);add(root,summary);status=text("",14);add(root,status);chapters=new LinearLayout(this);chapters.setOrientation(LinearLayout.VERTICAL);add(root,chapters);
        LinearLayout actions=new LinearLayout(this);root.addView(actions);all=button("Выбрать все");none=button("Снять выделение");actions.addView(all,new LinearLayout.LayoutParams(0,-2,1));actions.addView(none,new LinearLayout.LayoutParams(0,-2,1));all.setOnClickListener(v->{for(CheckBox c:checks)if(c.isEnabled())c.setChecked(true);});none.setOnClickListener(v->{for(CheckBox c:checks)c.setChecked(false);});
        download=button("Скачать выбранные");add(root,download);download.setOnClickListener(v->confirm(false));Button whole=button("Скачать всю книгу");add(root,whole);whole.setOnClickListener(v->confirm(true));
        LinearLayout controls=new LinearLayout(this);root.addView(controls);Button pause=button("Пауза");Button resume=button("Продолжить");Button cancel=button("Отменить");controls.addView(pause,new LinearLayout.LayoutParams(0,-2,1));controls.addView(resume,new LinearLayout.LayoutParams(0,-2,1));controls.addView(cancel,new LinearLayout.LayoutParams(0,-2,1));pause.setOnClickListener(v->command(DownloadWorker.PAUSE));resume.setOnClickListener(v->command(DownloadWorker.START));cancel.setOnClickListener(v->command(DownloadWorker.CANCEL));overall=text("",14);add(root,overall);
        handler.postDelayed(new Runnable(){public void run(){showJob();handler.postDelayed(this,1200);}},1200);
    }
    void fetch(){String s=address.getText().toString().trim();find.setEnabled(false);status.setText("Загружаю страницу…");new Thread(()->{try{KvuheParser.Book result=KvuheParser.fetch(s);runOnUiThread(()->{preview=result;render();find.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Ошибка импорта: "+e.getMessage());find.setEnabled(true);});}}).start();}
    void render(){if(preview==null)return;if(!preview.cover.isEmpty()){new Thread(()->{try{java.net.URL u=new java.net.URL(preview.cover);java.net.HttpURLConnection c=(java.net.HttpURLConnection)u.openConnection();c.setConnectTimeout(9000);c.setReadTimeout(9000);try(java.io.InputStream in=c.getInputStream()){android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeStream(in);runOnUiThread(()->{if(bitmap!=null){coverPreview.setImageBitmap(bitmap);coverPreview.setVisibility(View.VISIBLE);}});}c.disconnect();}catch(Exception ignored){}}).start();}title.setText(preview.title);long seconds=0;for(KvuheParser.Chapter c:preview.chapters)seconds+=c.seconds;summary.setText("Глав: "+preview.chapters.size()+" · Продолжительность: "+format(seconds));status.setText(preview.warning.isEmpty()?"Проверьте права на скачивание перед загрузкой.":preview.warning);chapters.removeAllViews();checks.clear();for(int i=0;i<preview.chapters.size();i++){KvuheParser.Chapter c=preview.chapters.get(i);CheckBox check=new CheckBox(this);check.setText(String.format(Locale.ROOT,"%03d. %s · %s%s",i+1,c.name,c.time,c.url.isEmpty()?" · MP3 не найден":""));check.setTextColor(foreground);check.setChecked(!c.url.isEmpty());check.setEnabled(!c.url.isEmpty());chapters.addView(check);checks.add(check);}}
    String format(long s){return String.format(Locale.ROOT,"%02d:%02d:%02d",s/3600,(s/60)%60,s%60);}
    void confirm(boolean all){if(preview==null){status.setText("Сначала найдите аудиокнигу");return;}BookImportManager.Job j=new BookImportManager.Job();j.source=preview.source;j.title=preview.title;j.cover=preview.cover;int selected=0;for(int i=0;i<preview.chapters.size();i++){KvuheParser.Chapter c=preview.chapters.get(i);j.chapters.add(c);boolean enabled=!c.url.isEmpty()&&(all||checks.get(i).isChecked());j.states.add(enabled?0:-1);if(enabled)selected++;}if(selected==0){status.setText("Не найдены разрешённые прямые MP3-ссылки для выбранных глав. Скачать нечего.");return;}new AlertDialog.Builder(this).setTitle("Подтвердите скачивание").setMessage("Глав: "+selected+". Продолжить только если у вас есть разрешение на загрузку этих материалов?").setNegativeButton("Отмена",null).setPositiveButton("Скачать",(d,w)->{BookImportManager.put(this,j);command(DownloadWorker.START);}).show();}
    void command(String action){String source=preview!=null?preview.source:address.getText().toString().trim();if(source.isEmpty())return;Intent i=new Intent(this,DownloadWorker.class).setAction(action).putExtra("source",source);try{if(DownloadWorker.START.equals(action)&&Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception e){status.setText("Не удалось начать загрузку: "+e.getMessage());}}
    void showJob(){String source=preview!=null?preview.source:address.getText().toString().trim();for(BookImportManager.Job j:BookImportManager.load(this))if(j.source.equals(source)){int complete=0;for(int x:j.states)if(x==100)complete++;overall.setText("Загрузка: "+j.status+" · "+complete+"/"+j.chapters.size()+" глав · "+(j.bytes/1024)+" KB"+(j.total>0?" / "+(j.total/1024)+" KB":"")+(j.error.isEmpty()?"":"\n"+j.error));for(int k=0;k<Math.min(j.states.size(),checks.size());k++){int state=j.states.get(k);CheckBox box=checks.get(k);String name=j.chapters.get(k).name;box.setText(String.format(Locale.ROOT,"%03d. %s · %s · %s",k+1,name,j.chapters.get(k).time,state==100?"Готово":state==-1?"Пропущено":state+"%"));}break;}}
}
